        nonlocal counter
        arrival[u] = counter
        lowlink[u] = counter
        counter += 1
        stack.append(u)
        on_stack.add(u)

        for v in adj.get(u, []):
            if v not in arrival:
                strong_connect(v)
                # v's component might reach further back than we knew
                lowlink[u] = min(lowlink[u], lowlink[v])
            elif v in on_stack:
                # Back edge into a component that is still open.
                # Note: arrival, not lowlink.
                lowlink[u] = min(lowlink[u], arrival[v])
            # else: v is in a closed component, that edge is one-way, skip

        # Could not reach anything older than itself, so u is a root.
        if lowlink[u] == arrival[u]:
            component = []
            while True:
                w = stack.pop()
                on_stack.discard(w)
                component.append(w)
                if w == u:
                    break
            components.append(component)

    for node in nodes:
        if node not in arrival:
            strong_connect(node)

    return components

