std::vector<std::vector<std::string>> tarjan(
    const std::vector<std::string>& nodes,
    const std::map<std::string, std::vector<std::string>>& adj) {
    std::map<std::string, int> arrival, lowlink;
    std::set<std::string> onStack;
    std::vector<std::string> stack;
    std::vector<std::vector<std::string>> components;
    int counter = 0;

    std::function<void(const std::string&)> strongConnect = [&](const std::string& u) {
        arrival[u] = counter;
        lowlink[u] = counter;
        counter++;
        stack.push_back(u);
        onStack.insert(u);

        auto it = adj.find(u);
        if (it != adj.end()) {
            for (const std::string& v : it->second) {
                if (!arrival.count(v)) {
                    strongConnect(v);
                    // v's component might reach further back than we knew
                    lowlink[u] = std::min(lowlink[u], lowlink[v]);
                } else if (onStack.count(v)) {
                    // Back edge into a component that is still open.
                    // Note: arrival, not lowlink.
                    lowlink[u] = std::min(lowlink[u], arrival[v]);
                }
                // else: v is in a closed component, that edge is one-way, skip
            }
        }

        // Could not reach anything older than itself, so u is a root.
        if (lowlink[u] == arrival[u]) {
            std::vector<std::string> component;
            std::string w;
            do {
                w = stack.back();
                stack.pop_back();
                onStack.erase(w);
                component.push_back(w);
            } while (w != u);
            components.push_back(component);
        }
    };

    for (const std::string& node : nodes) {
        if (!arrival.count(node)) strongConnect(node);
    }
    return components;
}
